/// Handles text sanitization, normalization, and truncation.\nclass TextSanitizer {\n  /// Removes leading/trailing whitespace, collapses internal whitespace,\n  /// removes emojis and special characters, and lowercases the text.\n  String sanitizeText(String text) {\n    if (text.isEmpty) return '';\n\n    // Remove emojis (broad range)\n    final noEmojis = text.replaceAll(\n      RegExp(\n        '[\\u{1F600}-\\u{1F64F}]|'  // emoticons\n        '[\\u{1F300}-\\u{1F5FF}]|'  // symbols & pictographs\n        '[\\u{1F680}-\\u{1F6FF}]|'  // transport & map\n        '[\\u{1F1E0}-\\u{1F1FF}]|'  // flags\n        '[\\u{2600}-\\u{26FF}]|'    // misc symbols\n        '[\\u{2700}-\\u{27BF}]',    // dingbats\n        multiLine: true,\n      ),\n      '',\n    );\n\n    // Remove special characters (keep alphanumeric, spaces, and basic punctuation)\n    final noSpecialChars = noEmojis.replaceAll(RegExp(r'[^a-zA-Z0-9\\s.,!?;:\\-\\()]'), '');\n\n    // Collapse whitespace and trim\n    final collapsed = noSpecialChars.replaceAll(RegExp(r'\\s+'), ' ').trim();\n\n    return collapsed;\n  }\n\n  /// Normalizes text case (default lowercase).\n  String normalizeCase(String text, {bool toUpperCase = false}) {\n    if (text.isEmpty) return '';\n    return toUpperCase ? text.toUpperCase() : text.toLowerCase();\n  }\n\n  /// Truncates text to a maximum length, appending '...' if truncated.\n  String truncateText(String text, int maxLength) {\n    if (text.length <= maxLength) return text;\n    return '\${text.substring(0, maxLength)}...';\n  }\n}\n
